input.command:
echo "=== word sorry anywhere in RiemannRoch ==="; grep -rn "sorry" --include=*.lean AlgebraicJacobian/RiemannRoch/ | wc -l; echo "=== real sorry terms (line starts / tactic position, excluding comments+docstrings) ==="; python3 - <<'PY'
import os,re
hits=[]
for r,_,fs in os.walk('AlgebraicJacobian/RiemannRoch'):
    for f in fs:
        if not f.endswith('.lean'): continue
        p=os.path.join(r,f); ind=False
        for i,ln in enumerate(open(p),1):
            t=ln.strip()
            if ind:
                if '-/' in t: ind=False
                continue
            if t.startswith('/-'):
                if not ('-/' in t and t.index('-/')>t.index('/-')): ind=True
                continue
            code=ln.split('--')[0]
            if re.search(r'(?<![A-Za-z_.])sorry(?![A-Za-z_])',code):
                hits.append(f'{p}:{i}: {t}')
print(len(hits))
for h in hits: print(h)
PY
